parameters.jsCode:
/**
 * PROCESSADOR DE CONTATOS WHATSAPP - COM DETECÇÃO DE DUPLICADOS
 * 
 * POSICIONAMENTO NO WORKFLOW:
 * Switch1 → [ESTE NÓ] → Supabase (indicacoes) → Processar contatos
 */

// Obtém os dados do webhook
const webhookData = $('Webhook EVO').item.json;

// Verifica se é mensagem de contatos (array ou único)
const messageType = webhookData.body?.message?.messageType;
const mediaType = webhookData.body?.message?.mediaType;

const isContactArray = messageType === 'ContactsArrayMessage' || mediaType === 'contact_array';
const isContactSingle = messageType === 'ContactMessage' || mediaType === 'contact';
const isContactMessage = isContactArray || isContactSingle;

if (!isContactMessage) {
  return { json: webhookData };
}

// ===== PROCESSAMENTO DE CONTATOS =====

function parseVCard(contact) {
  const vcard = contact.vcard || '';
  const parsed = {
    nomeExibicao: contact.displayName || 'Sem nome',
    telefones: [],
    nome: {
      completo: '',
      formatado: ''
    }
  };

  if (!vcard) return parsed;

  const fnMatch = vcard.match(/FN:(.+)/);
  if (fnMatch) {
    parsed.nome.completo = fnMatch[1].trim();
  }

  const nMatch = vcard.match(/N:(.+)/);
  if (nMatch) {
    parsed.nome.formatado = nMatch[1].trim();
  }

  // ABORDAGEM 1: Formato com waid (padrão WhatsApp)
  const telRegexWaid = /TEL;[^:]*waid=([^:;\s]+)(?::([^\n]+))?/g;
  let match;

  while ((match = telRegexWaid.exec(vcard)) !== null) {
    const numeroSujo = match[1];
    const numeroLimpo = numeroSujo.replace(/\D/g, '');
    const numeroFormatado = match[2]?.trim() || numeroSujo;

    if (numeroLimpo && numeroLimpo.length >= 10) {
      parsed.telefones.push({
        tipo: 'CELL',
        whatsappId: numeroLimpo,
        numeroFormatado: numeroFormatado,
        numeroLimpo: numeroLimpo,
        linkWhatsApp: `https://wa.me/${numeroLimpo}`
      });
    }
  }

  // ABORDAGEM 2: Qualquer linha TEL (sem waid)
  const telRegexGenerico = /TEL[^:]*:([^\n\r]+)/g;

  while ((match = telRegexGenerico.exec(vcard)) !== null) {
    const numeroSujo = match[1].trim();
    const numeroLimpo = numeroSujo.replace(/\D/g, '');

    const jaExiste = parsed.telefones.some(t => t.numeroLimpo === numeroLimpo);

    if (numeroLimpo && numeroLimpo.length >= 10 && !jaExiste) {
      parsed.telefones.push({
        tipo: 'CELL',
        whatsappId: numeroLimpo,
        numeroFormatado: numeroSujo,
        numeroLimpo: numeroLimpo,
        linkWhatsApp: `https://wa.me/${numeroLimpo}`
      });
    }
  }

  return parsed;
}

// ===== EXTRAI CONTATOS DO PAYLOAD =====
let contacts = [];

if (isContactArray) {
  contacts = webhookData.body?.message?.content?.contacts || [];
} else if (isContactSingle) {
  const singleContact = webhookData.body?.message?.content;
  if (singleContact) {
    contacts = [singleContact];
  }
}

// Processa todos os contatos
const contatosProcessados = contacts.map(contact => parseVCard(contact));

// Filtra contatos válidos
const contatosValidos = contatosProcessados.filter(c => c.telefones.length > 0);
const contatosSemTelefone = contatosProcessados.filter(c => c.telefones.length === 0);

// Se não houver contatos válidos
if (contatosValidos.length === 0) {
  const tipoMensagem = isContactSingle ? 'um contato' : `${contacts.length} contato(s)`;
  const resultado = {
    ...webhookData,
    contatosProcessados: {
      tipo: 'compartilhamento_contatos_invalido',
      tipoOriginal: messageType,
      quantidade: 0,
      erro: true,
      mensagem: `Nenhum contato válido foi enviado.`,
      contatosSemTelefone: contatosSemTelefone.map(c => c.nomeExibicao),
      textoParaIA: `O usuário enviou ${tipoMensagem}, mas nenhum possui número de telefone válido.`
    },
    body: {
      ...webhookData.body,
      message: {
        ...webhookData.body.message,
        text: `O usuário enviou ${tipoMensagem}, mas nenhum possui número de telefone válido.`
      }
    }
  };

  return { json: resultado };
}

// Dados do remetente
const remoteJid = webhookData.body?.message?.sender || '';
const pushName = webhookData.body?.message?.senderName || webhookData.body?.chat?.name || 'Usuário';
const telefoneRemetente = remoteJid.replace('@s.whatsapp.net', '');

// ===== BUSCA INDICAÇÕES DO SUPABASE E VERIFICA DUPLICADOS =====

let totalIndicacoesAtuais = 0;
let telefonesJaCadastrados = [];

try {
  const indicacoesDoSupabase = $('Indicacoes').all();

  // Filtra itens válidos (ignora objetos vazios E objetos sem telefone)
  const indicacoesValidas = indicacoesDoSupabase.filter(item => {
    const json = item.json || {};
    // Verifica se tem conteúdo E se tem o campo telefones_indicados
    return Object.keys(json).length > 0 && json.telefones_indicados;
  });

  totalIndicacoesAtuais = indicacoesValidas.length;

  // Extrai todos os telefones já cadastrados (NORMALIZA para comparar)
  telefonesJaCadastrados = indicacoesValidas
    .map(ind => {
      const tel = ind.json.telefones_indicados;
      // Remove tudo que não é número para comparar
      return String(tel).replace(/\D/g, '');
    })
    .filter(Boolean); // Remove nulos/vazios

  console.log('📊 Total de indicações no banco:', totalIndicacoesAtuais);
  console.log('📞 Telefones já cadastrados (normalizados):', telefonesJaCadastrados);

} catch (error) {
  console.log('⚠️ Erro ao buscar indicações:', error.message);
  // Em caso de erro, mantém zerado
  totalIndicacoesAtuais = 0;
  telefonesJaCadastrados = [];
}

// ===== SEPARA CONTATOS NOVOS E DUPLICADOS =====

const contatosNovos = [];
const contatosDuplicados = [];
const nomesProcessados = new Set(); // Controla nomes únicos

contatosValidos.forEach(contato => {
  const nomeNormalizado = contato.nomeExibicao.trim().toLowerCase();

  // Se já processamos esse nome, pula
  if (nomesProcessados.has(nomeNormalizado)) {
    console.log(`⚠️ Nome duplicado no mesmo envio: ${contato.nomeExibicao}`);
    return;
  }

  // Verifica se ALGUM telefone desse contato já existe
  const algumTelefoneJaExiste = contato.telefones.some(tel => 
    telefonesJaCadastrados.includes(tel.numeroLimpo)
  );

  // Pega o primeiro telefone válido
  const telefonesPrincipais = contato.telefones[0];

  console.log(`🔍 Verificando: ${contato.nomeExibicao} (${contato.telefones.length} telefone(s))`);
  console.log(`   → Já cadastrado? ${algumTelefoneJaExiste}`);

  if (algumTelefoneJaExiste) {
    // JÁ EXISTE
    contatosDuplicados.push({
      nome: contato.nomeExibicao,
      telefone: telefonesPrincipais.numeroLimpo,
      telefoneFormatado: telefonesPrincipais.numeroFormatado,
      telefonesAdicionais: contato.telefones.length > 1 ? contato.telefones.length - 1 : 0
    });
    console.log('   ❌ DUPLICADO!');
  } else {
    // É NOVO - adiciona com TODOS os telefones, mas conta como 1 indicação
    contatosNovos.push({
      nome: contato.nomeExibicao,
      telefone: telefonesPrincipais.numeroLimpo,
      telefoneFormatado: telefonesPrincipais.numeroFormatado,
      whatsappLink: telefonesPrincipais.linkWhatsApp,
      telefones: contato.telefones, // Mantém todos os telefones
      totalTelefones: contato.telefones.length
    });
    console.log(`   ✅ NOVO! (${contato.telefones.length} telefone(s))`);
  }

  nomesProcessados.add(nomeNormalizado);
});

console.log('📈 Resultado: Novos =', contatosNovos.length, '| Duplicados =', contatosDuplicados.length);

// ===== FORMATA MENSAGEM PARA A IA =====

let resumoParaIA = '';

// Se houver contatos novos
if (contatosNovos.length > 0) {
  const textoQuantidade = contatosNovos.length === 1 
    ? 'compartilhou 1 contato novo' 
    : `compartilhou ${contatosNovos.length} contatos novos`;

  const listaContatosNovos = contatosNovos.map((c, idx) => {
    const infoTelefones = c.totalTelefones > 1 
      ? ` (${c.totalTelefones} telefones)` 
      : '';
    return `${idx + 1}. ${c.nome} - ${c.telefoneFormatado}${infoTelefones}`;
  }).join('\n');

  resumoParaIA = `O usuário ${pushName} ${textoQuantidade}:\n\n${listaContatosNovos}`;
} else {
  resumoParaIA = `O usuário ${pushName} enviou contatos, mas todos já foram cadastrados anteriormente.`;
}

// Aviso sobre contatos sem telefone
if (contatosSemTelefone.length > 0) {
  resumoParaIA += `\n\nNota: ${contatosSemTelefone.length} contato(s) sem telefone foram ignorados: ${contatosSemTelefone.map(c => c.nomeExibicao).join(', ')}`;
}

// Aviso sobre duplicados
if (contatosDuplicados.length > 0) {
  const listaDuplicados = contatosDuplicados.map(c => c.nome).join(', ');
  resumoParaIA += `\n\nNota: ${contatosDuplicados.length} contato(s) duplicado(s) foram ignorados (já cadastrados): ${listaDuplicados}`;
}

// ===== CALCULA PROGRESSO (APENAS COM NOVOS) =====

const novasIndicacoes = contatosNovos.length;
const totalDepoisDeAdicionar = totalIndicacoesAtuais + novasIndicacoes;

const multiploAnterior = Math.floor(totalIndicacoesAtuais / 5) * 5;
const multiploAtual = Math.floor(totalDepoisDeAdicionar / 5) * 5;
const cruzouMultiploDe5 = multiploAtual > multiploAnterior;

const proximoMultiplo = Math.ceil(totalDepoisDeAdicionar / 5) * 5;
const faltamParaProximoMultiplo = proximoMultiplo - totalDepoisDeAdicionar;

// Mensagem de progresso
let mensagemProgresso = '';

if (novasIndicacoes > 0) {
  if (cruzouMultiploDe5) {
    mensagemProgresso = `\n\nIMPORTANTE: O cliente acabou de atingir ${multiploAtual} indicações!`;
  } else if (faltamParaProximoMultiplo === 0) {
    mensagemProgresso = `\n\nCliente está em ${totalDepoisDeAdicionar} indicações.`;
  } else {
    mensagemProgresso = `\n\nProgresso: ${totalDepoisDeAdicionar} indicações. Faltam ${faltamParaProximoMultiplo} para atingir ${proximoMultiplo}.`;
  }

  resumoParaIA += mensagemProgresso;
}

// ===== ESTRUTURA FINAL =====

const resultado = {
  ...webhookData,

  contatosProcessados: {
    tipo: 'compartilhamento_contatos',
    tipoOriginal: messageType,
    quantidade: contatosNovos.length,
    quantidadeTotal: contatosProcessados.length,
    quantidadeSemTelefone: contatosSemTelefone.length,
    quantidadeDuplicados: contatosDuplicados.length,
    quantidadeNovos: contatosNovos.length,

    remetente: {
      nome: pushName,
      telefone: telefoneRemetente,
      jid: remoteJid
    },

    contatos: contatosValidos,
    contatosNovos: contatosNovos,
    contatosDuplicados: contatosDuplicados,

    contatosIgnorados: [
      ...contatosSemTelefone.map(c => ({
        nome: c.nomeExibicao,
        motivo: 'sem_telefone'
      })),
      ...contatosDuplicados.map(c => ({
        nome: c.nome,
        motivo: 'duplicado'
      }))
    ],

    indicacoes: contatosNovos, // APENAS NOVOS para inserir no banco

    indicacoesStatus: {
      totalAntesDeAdicionar: totalIndicacoesAtuais,
      novasIndicacoes: novasIndicacoes,
      indicacoesDuplicadas: contatosDuplicados.length,
      totalDepoisDeAdicionar: totalDepoisDeAdicionar,
      multiploAtingido: multiploAtual,
      cruzouMultiploDe5: cruzouMultiploDe5,
      proximoMultiplo: proximoMultiplo,
      faltamParaProximoMultiplo: faltamParaProximoMultiplo
    },

    textoParaIA: resumoParaIA,

    listaNomes: contatosNovos.map(c => c.nome),
    listaTelefones: contatosNovos.map(c => c.telefone),
    listaTelefonesDuplicados: contatosDuplicados.map(c => c.telefone),

    processadoEm: new Date().toISOString()
  },

  body: {
    ...webhookData.body,
    message: {
      ...webhookData.body.message,
      text: resumoParaIA
    }
  }
};

return { json: resultado };

/**
 * OUTPUTS:
 * 
 * {{ $json.contatosProcessados.indicacoes }}
 *    → Array com APENAS contatos NOVOS (não duplicados) para inserir no Supabase
 * 
 * {{ $json.contatosProcessados.quantidadeNovos }}
 *    → Número de contatos novos
 * 
 * {{ $json.contatosProcessados.quantidadeDuplicados }}
 *    → Número de contatos duplicados
 * 
 * {{ $json.contatosProcessados.textoParaIA }}
 *    → Resumo completo com avisos de duplicados e progresso
 */

let phoneNumber = $input.first().json.wa_chatid;

// Remove qualquer sufixo que possa vir (como @s.whatsapp.net)
phoneNumber = phoneNumber.split('@')[0];

// Verifica se é um número brasileiro (começa com 55)
if (phoneNumber.startsWith('55')) {
  let ddd = phoneNumber.substring(2, 4); // Extrai o DDD (2 dígitos)
  let numero = phoneNumber.substring(4); // Extrai o resto do número

  // Se o número tiver apenas 8 dígitos, adiciona o 9
  if (numero.length === 8) {
    phoneNumber = '55' + ddd + '9' + numero;
  }
}

// Retorna apenas o número formatado
return {
  json: {
    wa_chatid: phoneNumber
  }
};

